  let tasks;
  const freshTasks=()=>seedTasks.map((x,i)=>({id:`v23-${i+1}`,owner:x[0],titleEn:x[1],titleFr:x[2],date:x[3],deadline:x[1].startsWith('Collect Shanghai factory quotation')?'2026-11-29':x[3],city:x[4],priority:x[5],status:'proposed',resultEn:x[6],resultFr:resultFrTranslation[x[6]]||x[6]}));
