    const dates=[...new Set(tasks.flatMap(x=>[x.date,x.deadline]))].sort();
    const filtered=tasks.filter(x=>(taskFilter.owner==='all'||x.owner===taskFilter.owner)&&(taskFilter.date==='all'||x.date===taskFilter.date||x.deadline===taskFilter.date)&&(taskFilter.city==='all'||x.city===taskFilter.city)&&(taskFilter.status==='all'||x.status===taskFilter.status));
