  document.querySelector('#page').addEventListener('click',async e=>{
    const planButton=e.target.closest('[data-plan]');if(planButton){journey.plan=planButton.dataset.plan;saveJourney();render();return}
    const card=e.target.closest('[data-day]');
    if(card&&e.target.closest('[data-edit]')){journey.title??={};journey.note??={};const title=prompt(t('Modifier le programme du jour','Edit this day’s plan'),card.querySelector('h2').textContent);if(title===null)return;const note=prompt(t('Détail ou rendez-vous proposé','Details or proposed meeting'),card.querySelector('p').textContent);if(note===null)return;journey.title[card.dataset.day]=title;journey.note[card.dataset.day]=note;saveJourney();render();return}
    const copy=e.target.closest('#copyJourneyFr,#copyJourneyEn');if(copy){const isEnglish=copy.id.endsWith('En');const program=plans[journey.plan||'A'].days.map(d=>`${d[0]} · ${routeName(d[1])} — ${d[4]} ${isEnglish?localized(d[2]):d[2]} (${isEnglish?localized(d[3]):d[3]})`).join('\n');try{await navigator.clipboard.writeText(program);alert(t('Programme copié','Plan copied'))}catch{prompt(t('Copier le programme','Copy the plan'),program)}}
    if(e.target.closest('#exportJourney'))document.querySelector('#exportProject').click();
    if(e.target.closest('#languageJourney'))document.querySelector('#language').click();
    if(e.target.closest('#newTask')){const form=document.querySelector('#taskForm');form.reset();form.elements.id.value='';form.elements.date.value=currentDate;form.elements.deadline.value=currentDate;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'});return}
    if(e.target.closest('[data-cancel-task]')){document.querySelector('#taskForm').hidden=true;return}
    const editTask=e.target.closest('[data-edit-task]');if(editTask){const task=tasks.find(x=>x.id===editTask.dataset.editTask),form=document.querySelector('#taskForm');if(!task||!form)return;form.elements.id.value=task.id;form.elements.title.value=taskTitle(task);form.elements.result.value=taskResult(task);form.elements.owner.value=task.owner;form.elements.date.value=task.date;form.elements.deadline.value=task.deadline;form.elements.city.value=task.city;form.elements.priority.value=task.priority;form.elements.status.value=task.status;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'});return}
    if(e.target.closest('#copyTasksTSV')){const rows=tasks.filter(x=>(taskFilter.owner==='all'||x.owner===taskFilter.owner)&&(taskFilter.date==='all'||x.date===taskFilter.date||x.deadline===taskFilter.date)&&(taskFilter.city==='all'||x.city===taskFilter.city)&&(taskFilter.status==='all'||x.status===taskFilter.status));const cols=[t('Responsable','Owner'),t('Tâche','Task'),t('Date','Date'),t('Échéance','Deadline'),t('Ville','City'),t('Priorité','Priority'),t('Statut','Status'),t('Résultat attendu','Expected result')];const clean=v=>String(v??'').replace(/[\t\r\n]+/g,' ').trim();const lines=[cols,...rows.map(x=>[x.owner,taskTitle(x),x.date,x.deadline,cityLabel(x.city),taskPriority(x.priority),taskStatus(x.status),taskResult(x)])].map(row=>row.map(clean).join('\t')).join('\n');try{await navigator.clipboard.writeText(lines);alert(t('Liste copiée au format TSV','Task list copied as TSV'))}catch{prompt(t('Copier les tâches au format TSV','Copy tasks as TSV'),lines)}}
  });
  document.querySelector('#page').addEventListener('submit',e=>{
    if(e.target.id!=='taskForm')return;e.preventDefault();const f=e.target,id=f.elements.id.value,owner=f.elements.owner.value,title=f.elements.title.value.trim(),result=f.elements.result.value.trim(),record={id:id||`task-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,owner,date:f.elements.date.value,deadline:f.elements.deadline.value,city:f.elements.city.value,priority:f.elements.priority.value,status:f.elements.status.value};
    if(id){const task=tasks.find(x=>x.id===id);if(!task)return;Object.assign(task,record);if(french){task.titleFr=title;task.resultFr=result}else{task.titleEn=title;task.resultEn=result}}
    else tasks.push({...record,titleEn:title,titleFr:title,resultEn:result,resultFr:result});saveTasks();f.hidden=true;render();
  });
