  const translateUi=()=>{
    if(french)return;
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
    while(node=walker.nextNode()){
      if(node.parentElement?.closest('script,style,textarea'))continue;
      const raw=node.nodeValue,trim=raw.trim();let translated=uiEn[trim];if(!translated&&trim.includes('RMB — environ'))translated=trim.replace('RMB — environ','RMB — approx.');if(translated&&translated!==trim)node.nodeValue=raw.replace(trim,translated);
    }
    document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(attr=>{const val=el.getAttribute(attr);if(uiEn[val])el.setAttribute(attr,uiEn[val])}));
    document.documentElement.lang='en';
  };
  if(!french){const nativePrompt=window.prompt.bind(window);window.prompt=(message='',...args)=>nativePrompt(uiEn[message]||message,...args)}
  const uiObserver=new MutationObserver(translateUi);uiObserver.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});translateUi();

